# Fixing Marching Cubes 33: ambiguity resolution for a manifold isosurface

**Problem class:** `js-marching-cubes-33-ambiguity-manifold-decider`
**Runtime:** Node 20+ · CommonJS
**Fix:** `mc33_standalone.js` — table-driven Chernyaev/Lewiner MC33, deterministic, edge-manifold, self-intersection-free.

## Root-cause analysis

A naive extractor walks the grid once and emits, for each of the 256 corner sign patterns, a fixed triangle list from one look-up table. This fails because:

1. **Six ambiguous face configurations.** A shared face with a checkerboard sign pattern (diagonal corners inside) has a bilinear saddle. The surface may join or separate the two inside corners. The classic table picks one fixed connection; two cells can then triangulate the *shared* face differently → cracks (interior boundary edges) and/or wrong topology. The choice must be a pure function of the four face values: the **asymptotic decider** `sign(face · A · (A·C − B·D))`.
2. **Body/interior ambiguity (cases 4, 10, 13).** Two non-adjacent inside corners: tunnel vs. two caps depends on the body saddle. Must be decided by `test_interior` (solve `t = −b/2a`, then test `At·Ct − Bt·Dt`).
3. **Missing extended tilings.** Cases 6.1.2, 7.3, 10.2, 12.2, 13.3, 13.4, 13.5 add an interior vertex; omitting them drops triangles or makes sheets meet at non-manifold edges.

Because `test_face` depends only on the shared 4 corners and `test_interior` only on one cell's 8 corners, neighbouring cells can never disagree about a shared feature — manifoldness is guaranteed by construction. Only true volume-boundary edges end up with one incident triangle.

## The fix

The core extractor (external tables) is below; `mc33_standalone.js` embeds the same tables as gzip+base64.

```js
"use strict";
const LUT = require("./mc33_tables.js");
const FLT_EPSILON = 1.1920928955078125e-7; // 2^-23
const fround = Math.fround;

function marchingCubes33(nx, ny, nz, data, iso) {
  const n = nx * ny * nz;
  const xv = new Int32Array(n).fill(-1), yv = new Int32Array(n).fill(-1), zv = new Int32Array(n).fill(-1);
  const VX = [], VY = [], VZ = [], NXa = [], NYa = [], NZa = [], F = [];
  const idx = (i, j, k) => i + nx * (j + ny * k);
  const D = (i, j, k) => data[idx(i, j, k)];
  const cube = new Float64Array(8);
  let _case = 0, _config = 0, _subconfig = 0, ci = 0, cj = 0, ck = 0;

  function get_x_grad(i,j,k){ if(i>0){ if(i<nx-1) return (D(i+1,j,k)-D(i-1,j,k))/2; return D(i,j,k)-D(i-1,j,k);} return D(i+1,j,k)-D(i,j,k); }
  function get_y_grad(i,j,k){ if(j>0){ if(j<ny-1) return (D(i,j+1,k)-D(i,j-1,k))/2; return D(i,j,k)-D(i,j-1,k);} return D(i,j+1,k)-D(i,j,k); }
  function get_z_grad(i,j,k){ if(k>0){ if(k<nz-1) return (D(i,j,k+1)-D(i,j,k-1))/2; return D(i,j,k)-D(i,j,k-1);} return D(i,j,k+1)-D(i,j,k); }

  function pushVertex(x,y,z){ const id=VX.length; VX.push(fround(x)); VY.push(fround(y)); VZ.push(fround(z)); return id; }
  function setNormal(id,x,y,z){ let u=Math.sqrt(x*x+y*y+z*z); if(u>0){x/=u;y/=u;z/=u;} NXa[id]=fround(x); NYa[id]=fround(y); NZa[id]=fround(z); }
  function add_x_vertex(){ const u=cube[0]/(cube[0]-cube[1]); const id=pushVertex(ci+u,cj,ck);
    NXa.push(0);NYa.push(0);NZa.push(0);
    setNormal(id,(1-u)*get_x_grad(ci,cj,ck)+u*get_x_grad(ci+1,cj,ck),(1-u)*get_y_grad(ci,cj,ck)+u*get_y_grad(ci+1,cj,ck),(1-u)*get_z_grad(ci,cj,ck)+u*get_z_grad(ci+1,cj,ck)); return id; }
  function add_y_vertex(){ const u=cube[0]/(cube[0]-cube[3]); const id=pushVertex(ci,cj+u,ck);
    NXa.push(0);NYa.push(0);NZa.push(0);
    setNormal(id,(1-u)*get_x_grad(ci,cj,ck)+u*get_x_grad(ci,cj+1,ck),(1-u)*get_y_grad(ci,cj,ck)+u*get_y_grad(ci,cj+1,ck),(1-u)*get_z_grad(ci,cj,ck)+u*get_z_grad(ci,cj+1,ck)); return id; }
  function add_z_vertex(){ const u=cube[0]/(cube[0]-cube[4]); const id=pushVertex(ci,cj,ck+u);
    NXa.push(0);NYa.push(0);NZa.push(0);
    setNormal(id,(1-u)*get_x_grad(ci,cj,ck)+u*get_x_grad(ci,cj,ck+1),(1-u)*get_y_grad(ci,cj,ck)+u*get_y_grad(ci,cj,ck+1),(1-u)*get_z_grad(ci,cj,ck)+u*get_z_grad(ci,cj,ck+1)); return id; }
  function add_c_vertex(){ let u=0,sx=0,sy=0,sz=0,snx=0,sny=0,snz=0;
    const acc=(id)=>{ if(id!==-1){++u; sx+=VX[id];sy+=VY[id];sz+=VZ[id]; snx+=NXa[id];sny+=NYa[id];snz+=NZa[id];}};
    acc(xv[idx(ci,cj,ck)]); acc(yv[idx(ci+1,cj,ck)]); acc(xv[idx(ci,cj+1,ck)]); acc(yv[idx(ci,cj,ck)]);
    acc(xv[idx(ci,cj,ck+1)]); acc(yv[idx(ci+1,cj,ck+1)]); acc(xv[idx(ci,cj+1,ck+1)]); acc(yv[idx(ci,cj,ck+1)]);
    acc(zv[idx(ci,cj,ck)]); acc(zv[idx(ci+1,cj,ck)]); acc(zv[idx(ci+1,cj+1,ck)]); acc(zv[idx(ci,cj+1,ck)]);
    const id=pushVertex(sx/u,sy/u,sz/u); NXa.push(0);NYa.push(0);NZa.push(0); setNormal(id,snx,sny,snz); return id; }

  for (let k=0;k<nz;++k) for (let j=0;j<ny;++j) for (let i=0;i<nx;++i) {
    cube[0]=D(i,j,k)-iso;
    cube[1]=i<nx-1?D(i+1,j,k)-iso:cube[0];
    cube[3]=j<ny-1?D(i,j+1,k)-iso:cube[0];
    cube[4]=k<nz-1?D(i,j,k+1)-iso:cube[0];
    if(Math.abs(cube[0])<FLT_EPSILON)cube[0]=FLT_EPSILON;
    if(Math.abs(cube[1])<FLT_EPSILON)cube[1]=FLT_EPSILON;
    if(Math.abs(cube[3])<FLT_EPSILON)cube[3]=FLT_EPSILON;
    if(Math.abs(cube[4])<FLT_EPSILON)cube[4]=FLT_EPSILON;
    ci=i;cj=j;ck=k; const p=idx(i,j,k);
    if(cube[0]<0){ if(cube[1]>0)xv[p]=add_x_vertex(); if(cube[3]>0)yv[p]=add_y_vertex(); if(cube[4]>0)zv[p]=add_z_vertex(); }
    else{ if(cube[1]<0)xv[p]=add_x_vertex(); if(cube[3]<0)yv[p]=add_y_vertex(); if(cube[4]<0)zv[p]=add_z_vertex(); }
  }

  // asymptotic (face) decider
  function test_face(face){ let A,B,C,Dd;
    switch(face){ case -1:case 1:A=cube[0];B=cube[4];C=cube[5];Dd=cube[1];break;
      case -2:case 2:A=cube[1];B=cube[5];C=cube[6];Dd=cube[2];break;
      case -3:case 3:A=cube[2];B=cube[6];C=cube[7];Dd=cube[3];break;
      case -4:case 4:A=cube[3];B=cube[7];C=cube[4];Dd=cube[0];break;
      case -5:case 5:A=cube[0];B=cube[3];C=cube[2];Dd=cube[1];break;
      case -6:case 6:A=cube[4];B=cube[7];C=cube[6];Dd=cube[5];break; default:A=B=C=Dd=0; }
    if(Math.abs(A*C-B*Dd)<FLT_EPSILON) return face>=0;
    return face*A*(A*C-B*Dd)>=0; }

  // body (interior) decider
  function test_interior(s){ let t,At=0,Bt=0,Ct=0,Dt=0,a,b,test=0,edge=-1;
    switch(_case){
      case 4: case 10:
        a=(cube[4]-cube[0])*(cube[6]-cube[2])-(cube[7]-cube[3])*(cube[5]-cube[1]);
        b=cube[2]*(cube[4]-cube[0])+cube[0]*(cube[6]-cube[2])-cube[1]*(cube[7]-cube[3])-cube[3]*(cube[5]-cube[1]);
        t=-b/(2*a); if(t<0||t>1) return s>0;
        At=cube[0]+(cube[4]-cube[0])*t; Bt=cube[3]+(cube[7]-cube[3])*t; Ct=cube[2]+(cube[6]-cube[2])*t; Dt=cube[1]+(cube[5]-cube[1])*t; break;
      case 6: case 7: case 12: case 13:
        switch(_case){ case 6:edge=LUT.test6[_config][2];break; case 7:edge=LUT.test7[_config][4];break;
          case 12:edge=LUT.test12[_config][3];break; case 13:edge=LUT.tiling13_5_1[_config][_subconfig][0];break; }
        switch(edge){
          case 0:t=cube[0]/(cube[0]-cube[1]);At=0;Bt=cube[3]+(cube[2]-cube[3])*t;Ct=cube[7]+(cube[6]-cube[7])*t;Dt=cube[4]+(cube[5]-cube[4])*t;break;
          case 1:t=cube[1]/(cube[1]-cube[2]);At=0;Bt=cube[0]+(cube[3]-cube[0])*t;Ct=cube[4]+(cube[7]-cube[4])*t;Dt=cube[5]+(cube[6]-cube[5])*t;break;
          case 2:t=cube[2]/(cube[2]-cube[3]);At=0;Bt=cube[1]+(cube[0]-cube[1])*t;Ct=cube[5]+(cube[4]-cube[5])*t;Dt=cube[6]+(cube[7]-cube[6])*t;break;
          case 3:t=cube[3]/(cube[3]-cube[0]);At=0;Bt=cube[2]+(cube[1]-cube[2])*t;Ct=cube[6]+(cube[5]-cube[6])*t;Dt=cube[7]+(cube[4]-cube[7])*t;break;
          case 4:t=cube[4]/(cube[4]-cube[5]);At=0;Bt=cube[7]+(cube[6]-cube[7])*t;Ct=cube[3]+(cube[2]-cube[3])*t;Dt=cube[0]+(cube[1]-cube[0])*t;break;
          case 5:t=cube[5]/(cube[5]-cube[6]);At=0;Bt=cube[4]+(cube[7]-cube[4])*t;Ct=cube[0]+(cube[3]-cube[0])*t;Dt=cube[1]+(cube[2]-cube[1])*t;break;
          case 6:t=cube[6]/(cube[6]-cube[7]);At=0;Bt=cube[5]+(cube[4]-cube[5])*t;Ct=cube[1]+(cube[0]-cube[1])*t;Dt=cube[2]+(cube[3]-cube[2])*t;break;
          case 7:t=cube[7]/(cube[7]-cube[4]);At=0;Bt=cube[6]+(cube[5]-cube[6])*t;Ct=cube[2]+(cube[1]-cube[2])*t;Dt=cube[3]+(cube[0]-cube[3])*t;break;
          case 8:t=cube[0]/(cube[0]-cube[4]);At=0;Bt=cube[3]+(cube[7]-cube[3])*t;Ct=cube[2]+(cube[6]-cube[2])*t;Dt=cube[1]+(cube[5]-cube[1])*t;break;
          case 9:t=cube[1]/(cube[1]-cube[5]);At=0;Bt=cube[0]+(cube[4]-cube[0])*t;Ct=cube[3]+(cube[7]-cube[3])*t;Dt=cube[2]+(cube[6]-cube[2])*t;break;
          case 10:t=cube[2]/(cube[2]-cube[6]);At=0;Bt=cube[1]+(cube[5]-cube[1])*t;Ct=cube[0]+(cube[4]-cube[0])*t;Dt=cube[3]+(cube[7]-cube[3])*t;break;
          case 11:t=cube[3]/(cube[3]-cube[7]);At=0;Bt=cube[2]+(cube[6]-cube[2])*t;Ct=cube[1]+(cube[5]-cube[1])*t;Dt=cube[0]+(cube[4]-cube[0])*t;break; }
        break; default: break; }
    if(At>=0)test++; if(Bt>=0)test+=2; if(Ct>=0)test+=4; if(Dt>=0)test+=8;
    switch(test){
      case 5: if(At*Ct-Bt*Dt<FLT_EPSILON) return s>0; break;
      case 10: if(At*Ct-Bt*Dt>=FLT_EPSILON) return s>0; break;
      case 7: case 11: case 13: case 14: case 15: return s<0; }
    return s>0; }

  function addTriangle(trig,nTri,v12){ const tv=[0,0,0];
    for(let t=0;t<3*nTri;++t){
      switch(trig[t]){
        case 0:tv[t%3]=xv[idx(ci,cj,ck)];break; case 1:tv[t%3]=yv[idx(ci+1,cj,ck)];break;
        case 2:tv[t%3]=xv[idx(ci,cj+1,ck)];break; case 3:tv[t%3]=yv[idx(ci,cj,ck)];break;
        case 4:tv[t%3]=xv[idx(ci,cj,ck+1)];break; case 5:tv[t%3]=yv[idx(ci+1,cj,ck+1)];break;
        case 6:tv[t%3]=xv[idx(ci,cj+1,ck+1)];break; case 7:tv[t%3]=yv[idx(ci,cj,ck+1)];break;
        case 8:tv[t%3]=zv[idx(ci,cj,ck)];break; case 9:tv[t%3]=zv[idx(ci+1,cj,ck)];break;
        case 10:tv[t%3]=zv[idx(ci+1,cj+1,ck)];break; case 11:tv[t%3]=zv[idx(ci,cj+1,ck)];break;
        case 12:tv[t%3]=v12;break; }
      if(t%3===2) F.push(tv[0],tv[1],tv[2]); } }

  for (let k=0;k<nz-1;++k) for (let j=0;j<ny-1;++j) for (let i=0;i<nx-1;++i) {
    let lut=0;
    for(let p=0;p<8;++p){ const xo=(p^(p>>1))&1,yo=(p>>1)&1,zo=(p>>2)&1;
      let v=D(i+xo,j+yo,k+zo)-iso; if(Math.abs(v)<FLT_EPSILON)v=FLT_EPSILON; cube[p]=v; if(v>0)lut+=1<<p; }
    ci=i;cj=j;ck=k; _config=LUT.cases[lut][1]; _case=LUT.cases[lut][0]; _subconfig=0; let v12=-1;
    switch(_case){
      case 0: break;
      case 1: addTriangle(LUT.tiling1[_config],1); break;
      case 2: addTriangle(LUT.tiling2[_config],2); break;
      case 3: if(test_face(LUT.test3[_config])) addTriangle(LUT.tiling3_2[_config],4); else addTriangle(LUT.tiling3_1[_config],2); break;
      case 4: if(test_interior(LUT.test4[_config])) addTriangle(LUT.tiling4_1[_config],2); else addTriangle(LUT.tiling4_2[_config],6); break;
      case 5: addTriangle(LUT.tiling5[_config],3); break;
      case 6: if(test_face(LUT.test6[_config][0])) addTriangle(LUT.tiling6_2[_config],5);
        else if(test_interior(LUT.test6[_config][1])) addTriangle(LUT.tiling6_1_1[_config],3);
        else { v12=add_c_vertex(); addTriangle(LUT.tiling6_1_2[_config],9,v12); } break;
      case 7:
        if(test_face(LUT.test7[_config][0]))_subconfig+=1; if(test_face(LUT.test7[_config][1]))_subconfig+=2; if(test_face(LUT.test7[_config][2]))_subconfig+=4;
        switch(_subconfig){
          case 0:addTriangle(LUT.tiling7_1[_config],3);break;
          case 1:addTriangle(LUT.tiling7_2[_config][0],5);break;
          case 2:addTriangle(LUT.tiling7_2[_config][1],5);break;
          case 3:v12=add_c_vertex();addTriangle(LUT.tiling7_3[_config][0],9,v12);break;
          case 4:addTriangle(LUT.tiling7_2[_config][2],5);break;
          case 5:v12=add_c_vertex();addTriangle(LUT.tiling7_3[_config][1],9,v12);break;
          case 6:v12=add_c_vertex();addTriangle(LUT.tiling7_3[_config][2],9,v12);break;
          case 7: if(test_interior(LUT.test7[_config][3]))addTriangle(LUT.tiling7_4_2[_config],9);else addTriangle(LUT.tiling7_4_1[_config],5);break; }
        break;
      case 8: addTriangle(LUT.tiling8[_config],2); break;
      case 9: addTriangle(LUT.tiling9[_config],4); break;
      case 10:
        if(test_face(LUT.test10[_config][0])){ if(test_face(LUT.test10[_config][1]))addTriangle(LUT.tiling10_1_1_[_config],4);
          else{v12=add_c_vertex();addTriangle(LUT.tiling10_2[_config],8,v12);} }
        else if(test_face(LUT.test10[_config][1])){v12=add_c_vertex();addTriangle(LUT.tiling10_2_[_config],8,v12);}
        else if(test_interior(LUT.test10[_config][2]))addTriangle(LUT.tiling10_1_1[_config],4);
        else addTriangle(LUT.tiling10_1_2[_config],8); break;
      case 11: addTriangle(LUT.tiling11[_config],4); break;
      case 12:
        if(test_face(LUT.test12[_config][0])){ if(test_face(LUT.test12[_config][1]))addTriangle(LUT.tiling12_1_1_[_config],4);
          else{v12=add_c_vertex();addTriangle(LUT.tiling12_2[_config],8,v12);} }
        else if(test_face(LUT.test12[_config][1])){v12=add_c_vertex();addTriangle(LUT.tiling12_2_[_config],8,v12);}
        else if(test_interior(LUT.test12[_config][2]))addTriangle(LUT.tiling12_1_1[_config],4);
        else addTriangle(LUT.tiling12_1_2[_config],8); break;
      case 13:
        if(test_face(LUT.test13[_config][0]))_subconfig+=1; if(test_face(LUT.test13[_config][1]))_subconfig+=2; if(test_face(LUT.test13[_config][2]))_subconfig+=4;
        if(test_face(LUT.test13[_config][3]))_subconfig+=8; if(test_face(LUT.test13[_config][4]))_subconfig+=16; if(test_face(LUT.test13[_config][5]))_subconfig+=32;
        switch(LUT.subconfig13[_subconfig]){
          case 0:addTriangle(LUT.tiling13_1[_config],4);break;
          case 1:addTriangle(LUT.tiling13_2[_config][0],6);break; case 2:addTriangle(LUT.tiling13_2[_config][1],6);break;
          case 3:addTriangle(LUT.tiling13_2[_config][2],6);break; case 4:addTriangle(LUT.tiling13_2[_config][3],6);break;
          case 5:addTriangle(LUT.tiling13_2[_config][4],6);break; case 6:addTriangle(LUT.tiling13_2[_config][5],6);break;
          case 7:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][0],10,v12);break; case 8:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][1],10,v12);break;
          case 9:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][2],10,v12);break; case 10:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][3],10,v12);break;
          case 11:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][4],10,v12);break; case 12:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][5],10,v12);break;
          case 13:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][6],10,v12);break; case 14:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][7],10,v12);break;
          case 15:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][8],10,v12);break; case 16:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][9],10,v12);break;
          case 17:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][10],10,v12);break; case 18:v12=add_c_vertex();addTriangle(LUT.tiling13_3[_config][11],10,v12);break;
          case 19:v12=add_c_vertex();addTriangle(LUT.tiling13_4[_config][0],12,v12);break; case 20:v12=add_c_vertex();addTriangle(LUT.tiling13_4[_config][1],12,v12);break;
          case 21:v12=add_c_vertex();addTriangle(LUT.tiling13_4[_config][2],12,v12);break; case 22:v12=add_c_vertex();addTriangle(LUT.tiling13_4[_config][3],12,v12);break;
          case 23:_subconfig=0; if(test_interior(LUT.test13[_config][6]))addTriangle(LUT.tiling13_5_1[_config][0],6);else addTriangle(LUT.tiling13_5_2[_config][0],10);break;
          case 24:_subconfig=1; if(test_interior(LUT.test13[_config][6]))addTriangle(LUT.tiling13_5_1[_config][1],6);else addTriangle(LUT.tiling13_5_2[_config][1],10);break;
          case 25:_subconfig=2; if(test_interior(LUT.test13[_config][6]))addTriangle(LUT.tiling13_5_1[_config][2],6);else addTriangle(LUT.tiling13_5_2[_config][2],10);break;
          case 26:_subconfig=3; if(test_interior(LUT.test13[_config][6]))addTriangle(LUT.tiling13_5_1[_config][3],6);else addTriangle(LUT.tiling13_5_2[_config][3],10);break;
          case 27:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][0],10,v12);break; case 28:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][1],10,v12);break;
          case 29:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][2],10,v12);break; case 30:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][3],10,v12);break;
          case 31:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][4],10,v12);break; case 32:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][5],10,v12);break;
          case 33:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][6],10,v12);break; case 34:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][7],10,v12);break;
          case 35:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][8],10,v12);break; case 36:v12=add_c_vertex();addTriangle(LUT.tiling13_3_[_config][9],10,v12);break;
